package com.fiap.hackgov.agriculture.internal.services;
import com.fiap.hackgov.agriculture.internal.DTOs.AgricultureDTOs.*;import com.fiap.hackgov.agriculture.internal.entities.*;import com.fiap.hackgov.agriculture.internal.repositories.*;import com.fiap.hackgov.cityhall_management.internal.entities.Employee;import com.fiap.hackgov.clients.internal.entities.Client;import com.fiap.hackgov.clients.internal.repositories.ClientRepository;import com.fiap.hackgov.shared.infra.exceptions.*;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
@Service @RequiredArgsConstructor
public class AgricultureService {
 private final AgriculturalServiceTypeRepository typeRepository;private final PaymentProofTypeRepository paymentTypeRepository;private final MachineryRepository machineryRepository;private final TractorDriverRepository driverRepository;private final AgriculturalServiceRequestRepository serviceRepository;private final OperationalControlRepository controlRepository;private final ClientRepository clientRepository;
 @Transactional public CatalogResponse catalog(Employee employee){Employee current=require(employee);UUID city=cityId(current);ensureDefaults(current);return new CatalogResponse(typeRepository.findByCityHall_IdOrderByAreaAscNameAsc(city).stream().map(t->new CatalogItem(t.getId(),t.getName(),"SERVICE_TYPE",t.getArea().name(),t.getHourlyValue(),t.isActive())).toList(),paymentTypeRepository.findByCityHall_IdOrderByNameAsc(city).stream().map(t->new CatalogItem(t.getId(),t.getName(),"PAYMENT_TYPE",null,null,t.isActive())).toList(),machineryRepository.findByCityHall_IdOrderByNameAsc(city).stream().map(t->new CatalogItem(t.getId(),t.getName(),"MACHINERY",null,null,t.isActive())).toList(),driverRepository.findByCityHall_IdOrderByNameAsc(city).stream().map(t->new CatalogItem(t.getId(),t.getName(),"DRIVER",null,null,t.isActive())).toList());}
 @Transactional public CatalogItem addCatalog(String kind,CatalogRequest request,Employee employee){Employee current=require(employee);return switch(kind.toUpperCase(Locale.ROOT)){case "SERVICE_TYPE"->{if(request.area()==null||request.hourlyValue()==null)throw new BusinessException("Area e valor sao obrigatorios");AgriculturalServiceType item=new AgriculturalServiceType();item.setCityHall(current.getCityHallId());item.setName(request.name().trim());item.setArea(request.area());item.setHourlyValue(request.hourlyValue());item=typeRepository.save(item);yield new CatalogItem(item.getId(),item.getName(),kind,item.getArea().name(),item.getHourlyValue(),true);}case "PAYMENT_TYPE"->{PaymentProofType item=new PaymentProofType();item.setCityHall(current.getCityHallId());item.setName(request.name().trim());item=paymentTypeRepository.save(item);yield new CatalogItem(item.getId(),item.getName(),kind,null,null,true);}case "MACHINERY"->{Machinery item=new Machinery();item.setCityHall(current.getCityHallId());item.setName(request.name().trim());item=machineryRepository.save(item);yield new CatalogItem(item.getId(),item.getName(),kind,null,null,true);}case "DRIVER"->{TractorDriver item=new TractorDriver();item.setCityHall(current.getCityHallId());item.setName(request.name().trim());item=driverRepository.save(item);yield new CatalogItem(item.getId(),item.getName(),kind,null,null,true);}default->throw new BusinessException("Tipo de cadastro invalido");};}
 @Transactional public Page<ServiceResponse> findAll(String query,Pageable pageable,Employee employee){Employee current=require(employee);Page<AgriculturalServiceRequest> page=serviceRepository.search(cityId(current),query==null?"":query.trim(),pageable);page.forEach(item->{if(item.shouldExpire(LocalDate.now())){item.setStatus(AgriculturalServiceRequest.Status.EXPIRED);serviceRepository.save(item);}});return page.map(this::response);}
 @Transactional public ServiceResponse create(ServiceRequest request,Employee employee){Employee current=require(employee);UUID city=cityId(current);Client client=clientRepository.findByIdAndCityHall_Id(request.clientId(),city).orElseThrow(()->new BusinessException("Cliente precisa pertencer a prefeitura"));AgriculturalServiceType type=typeRepository.findByIdAndCityHall_Id(request.serviceTypeId(),city).orElseThrow(()->new BusinessException("Tipo de servico precisa pertencer a prefeitura"));AgriculturalServiceRequest item=new AgriculturalServiceRequest();item.setCityHall(current.getCityHallId());item.setClient(client);item.setServiceType(type);item.setCreatedBy(current);apply(item,request,city);item=serviceRepository.save(item);OperationalControl control=new OperationalControl();control.setServiceRequest(item);controlRepository.save(control);return response(item);}
 @Transactional public ServiceResponse update(UUID id,ServiceRequest request,Employee employee){Employee current=require(employee);UUID city=cityId(current);AgriculturalServiceRequest item=find(id,city);item.setClient(clientRepository.findByIdAndCityHall_Id(request.clientId(),city).orElseThrow(()->new BusinessException("Cliente precisa pertencer a prefeitura")));item.setServiceType(typeRepository.findByIdAndCityHall_Id(request.serviceTypeId(),city).orElseThrow(()->new BusinessException("Tipo de servico precisa pertencer a prefeitura")));apply(item,request,city);return response(serviceRepository.save(item));}
 @Transactional public ControlResponse updateControl(UUID serviceId,ControlRequest request,Employee employee){UUID city=cityId(require(employee));AgriculturalServiceRequest service=find(serviceId,city);OperationalControl control=controlRepository.findByServiceRequest_Id(serviceId).orElseGet(()->{OperationalControl value=new OperationalControl();value.setServiceRequest(service);return value;});control.setMachinery(request.machineryId()==null?null:machineryRepository.findByIdAndCityHall_Id(request.machineryId(),city).orElseThrow(()->new BusinessException("Maquinario precisa pertencer a prefeitura")));control.setTractorDriver(request.tractorDriverId()==null?null:driverRepository.findByIdAndCityHall_Id(request.tractorDriverId(),city).orElseThrow(()->new BusinessException("Tratorista precisa pertencer a prefeitura")));if(request.initialHourMeter()!=null&&request.finalHourMeter()!=null&&request.finalHourMeter().compareTo(request.initialHourMeter())<0)throw new BusinessException("Horimetro final nao pode ser menor que o inicial");control.setInitialHourMeter(request.initialHourMeter());control.setFinalHourMeter(request.finalHourMeter());return controlResponse(controlRepository.save(control),service);}
 @Transactional public ServiceResponse uploadProof(UUID id,MultipartFile file,Employee employee){AgriculturalServiceRequest item=find(id,cityId(require(employee)));if(file==null||file.isEmpty()||file.getSize()>10L*1024*1024)throw new BusinessException("Comprovante invalido ou maior que 10 MB");try{byte[] content=file.getBytes();if(content.length>1&&content[0]=='M'&&content[1]=='Z')throw new BusinessException("Conteudo de arquivo invalido");item.setPaymentProof(content);item.setPaymentProofName(Optional.ofNullable(file.getOriginalFilename()).orElse("comprovante"));item.setPaymentProofContentType(Optional.ofNullable(file.getContentType()).orElse("application/octet-stream"));return response(serviceRepository.save(item));}catch(IOException e){throw new BusinessException("Nao foi possivel ler o comprovante");}}
 private void apply(AgriculturalServiceRequest item,ServiceRequest request,UUID city){if(request.requestedHours().signum()<=0)throw new BusinessException("Horas solicitadas precisam ser maiores que zero");item.setProtocol(request.protocol()==null||request.protocol().isBlank()?"PAT-"+LocalDate.now().getYear()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase():request.protocol().trim());item.setStatus(request.status()==null?AgriculturalServiceRequest.Status.PENDING:request.status());item.setScheduledDate(request.scheduledDate());item.setRequestedHours(request.requestedHours());item.setAddress(request.address().trim());item.setDonation(request.donation());if(request.donation()){if(request.donationOrigin()==null||request.donationOrigin().isBlank())throw new BusinessException("Informe a origem da doacao");item.setDonationOrigin(request.donationOrigin().trim());item.setAmount(null);item.setPaymentDate(null);item.setFunderId("");item.setPaymentProofType(null);item.setFunderAmount(null);item.setPaymentProof(null);}else{item.setDonationOrigin("");item.setAmount(item.getServiceType().getHourlyValue().multiply(request.requestedHours()).setScale(2,java.math.RoundingMode.HALF_UP));item.setPaymentDate(request.paymentDate());item.setFunderId(request.funderId()==null?"":request.funderId().trim());item.setPaymentProofType(request.paymentProofTypeId()==null?null:paymentTypeRepository.findByIdAndCityHall_Id(request.paymentProofTypeId(),city).orElseThrow(()->new BusinessException("Tipo de comprovante precisa pertencer a prefeitura")));item.setFunderAmount(request.funderAmount());}if(item.shouldExpire(LocalDate.now()))item.setStatus(AgriculturalServiceRequest.Status.EXPIRED);}
 private AgriculturalServiceRequest find(UUID id,UUID city){return serviceRepository.findByIdAndCityHall_Id(id,city).orElseThrow(()->new ResourceNotFoundException("Servico de patrulha nao encontrado"));}
 private ServiceResponse response(AgriculturalServiceRequest item){OperationalControl control=controlRepository.findByServiceRequest_Id(item.getId()).orElse(null);return new ServiceResponse(item.getId(),item.getProtocol(),item.getStatus(),item.getClient().getId(),item.getClient().getFullName(),item.getScheduledDate(),item.getServiceType().getId(),item.getServiceType().getName(),item.getRequestedHours(),item.getAddress(),item.getAmount(),item.getPaymentDate(),item.expirationDate(),item.getFunderId(),item.getPaymentProofType()==null?null:item.getPaymentProofType().getId(),item.getFunderAmount(),item.isDonation(),item.getDonationOrigin(),item.getPaymentProof()!=null,control==null?null:controlResponse(control,item),item.getCreatedAt(),item.getUpdatedAt());}
 private ControlResponse controlResponse(OperationalControl control,AgriculturalServiceRequest service){BigDecimal performed=control.performedHours(),remaining=performed==null?service.getRequestedHours():service.getRequestedHours().subtract(performed);String status=performed==null?"WAITING":remaining.signum()>0?"PENDING_HOURS":remaining.signum()<0?"EXCEEDED_HOURS":"COMPLETED_HOURS";return new ControlResponse(control.getId(),control.getMachinery()==null?null:control.getMachinery().getId(),control.getMachinery()==null?null:control.getMachinery().getName(),control.getTractorDriver()==null?null:control.getTractorDriver().getId(),control.getTractorDriver()==null?null:control.getTractorDriver().getName(),control.getInitialHourMeter(),control.getFinalHourMeter(),performed,remaining,status);}
 private Employee require(Employee employee){if(employee==null)throw new UnauthorizedException("E necessario estar autenticado");cityId(employee);return employee;}private UUID cityId(Employee employee){if(employee.getCityHallId()==null)throw new BusinessException("Usuario sem prefeitura");return employee.getCityHallId().getId();}
 private void ensureDefaults(Employee employee){UUID city=cityId(employee);if(typeRepository.findByCityHall_IdOrderByAreaAscNameAsc(city).isEmpty()){AgriculturalServiceType type=new AgriculturalServiceType();type.setCityHall(employee.getCityHallId());type.setName("Hora maquina rural");type.setArea(AgriculturalServiceType.Area.RURAL);type.setHourlyValue(new BigDecimal("250.00"));typeRepository.save(type);}if(paymentTypeRepository.findByCityHall_IdOrderByNameAsc(city).isEmpty()){PaymentProofType type=new PaymentProofType();type.setCityHall(employee.getCityHallId());type.setName("Comprovante FUNDER");paymentTypeRepository.save(type);}if(machineryRepository.findByCityHall_IdOrderByNameAsc(city).isEmpty()){Machinery machinery=new Machinery();machinery.setCityHall(employee.getCityHallId());machinery.setName("Trator municipal");machineryRepository.save(machinery);}if(driverRepository.findByCityHall_IdOrderByNameAsc(city).isEmpty()){TractorDriver driver=new TractorDriver();driver.setCityHall(employee.getCityHallId());driver.setName("Operador municipal");driverRepository.save(driver);}}
}
